#!/usr/bin/env python3
from __future__ import annotations

import argparse
import ast
import json
import re
import sys
from collections import Counter
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE_EXTENSIONS = {".py", ".js", ".jsx", ".css", ".html"}
EXCLUDED_PARTS = {"node_modules", ".pytest_cache", "__pycache__", "dist", ".git", ".venv"}
SUSPICIOUS_MARKERS = [
    "as an ai",
    "generated by chatgpt",
    "chatgpt",
    "todo: implement",
    "lorem ipsum",
    "placeholder implementation",
]


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Audit source composition and release hygiene.")
    parser.add_argument("--root", type=Path, default=ROOT)
    parser.add_argument("--json", action="store_true")
    return parser.parse_args()


def source_files(root: Path) -> list[Path]:
    return [
        path for path in root.rglob("*")
        if path.is_file()
        and path.suffix.lower() in SOURCE_EXTENSIONS
        and not EXCLUDED_PARTS.intersection(path.parts)
    ]


def classify(path: Path, root: Path) -> str:
    relative = path.relative_to(root)
    parts = relative.parts
    if "tests" in parts:
        return "tests"
    if parts and parts[0] == "backend":
        return "backend"
    if parts and parts[0] == "frontend":
        return "frontend"
    return "other"


def count_lines(path: Path) -> tuple[int, int]:
    lines = path.read_text(encoding="utf-8", errors="ignore").splitlines()
    non_empty = sum(1 for line in lines if line.strip())
    return len(lines), non_empty


def python_ast_stats(path: Path) -> dict[str, int]:
    try:
        tree = ast.parse(path.read_text(encoding="utf-8"))
    except SyntaxError:
        return {"functions": 0, "classes": 0, "imports": 0, "syntax_errors": 1}
    return {
        "functions": sum(isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) for node in ast.walk(tree)),
        "classes": sum(isinstance(node, ast.ClassDef) for node in ast.walk(tree)),
        "imports": sum(isinstance(node, (ast.Import, ast.ImportFrom)) for node in ast.walk(tree)),
        "syntax_errors": 0,
    }


def scan_markers(path: Path) -> list[dict[str, str | int]]:
    findings = []
    for number, line in enumerate(path.read_text(encoding="utf-8", errors="ignore").splitlines(), start=1):
        lowered = line.lower()
        for marker in SUSPICIOUS_MARKERS:
            if marker in lowered:
                findings.append({"file": str(path), "line": number, "marker": marker})
    return findings


def main() -> int:
    args = parse_args()
    root = args.root.resolve()
    files = source_files(root)
    categories = Counter()
    extensions = Counter()
    total_lines = 0
    non_empty_lines = 0
    ast_totals = Counter()
    suspicious = []
    largest = []

    for path in files:
        lines, non_empty = count_lines(path)
        total_lines += lines
        non_empty_lines += non_empty
        categories[classify(path, root)] += lines
        extensions[path.suffix.lower()] += lines
        largest.append((lines, str(path.relative_to(root))))
        if path.resolve() != Path(__file__).resolve():
            suspicious.extend(scan_markers(path))
        if path.suffix == ".py":
            ast_totals.update(python_ast_stats(path))

    largest.sort(reverse=True)
    report = {
        "root": str(root),
        "source_files": len(files),
        "lines_total": total_lines,
        "non_empty_lines": non_empty_lines,
        "lines_by_area": dict(categories),
        "lines_by_extension": dict(extensions),
        "python_ast": dict(ast_totals),
        "largest_files": [{"file": name, "lines": lines} for lines, name in largest[:20]],
        "suspicious_markers": suspicious,
        "checks": {
            "python_syntax": ast_totals["syntax_errors"] == 0,
            "no_suspicious_markers": len(suspicious) == 0,
            "substantial_codebase": total_lines >= 9500,
        },
    }
    report["passed"] = all(report["checks"].values())
    if args.json:
        print(json.dumps(report, ensure_ascii=False, indent=2))
    else:
        print(f"Source files: {report['source_files']}")
        print(f"Source lines: {report['lines_total']} ({report['non_empty_lines']} non-empty)")
        print(f"By area: {report['lines_by_area']}")
        print(f"Python: {report['python_ast']}")
        print(f"Suspicious markers: {len(suspicious)}")
        print(f"Audit: {'PASS' if report['passed'] else 'FAIL'}")
    return 0 if report["passed"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
